<?php
namespace App\Http\Controllers;
use App\Models\AppSetting; use App\Services\MailSettings; use App\Mail\ContributorNotification; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Facades\Mail;
class SettingsController extends Controller { public function edit(){ $keys=['site_name','logo','currency_symbol','pdf_footer','mail_sandbox_mode','mail_gmail_address','mail_from_name','mailtrap_host','mailtrap_port','mailtrap_username'];$settings=[];foreach($keys as $key)$settings[$key]=AppSetting::value($key,$key==='currency_symbol'?'₹':null);$settings['has_gmail_password']=!!AppSetting::value('mail_gmail_app_password');$settings['has_mailtrap_password']=!!AppSetting::value('mailtrap_password');return view('settings.edit',compact('settings'));} public function update(Request $r){$data=$r->validate(['site_name'=>'required|max:100','currency_symbol'=>'required|max:10','pdf_footer'=>'nullable|max:500','logo'=>'nullable|image|max:2048','mail_sandbox_mode'=>'nullable','mail_gmail_address'=>'nullable|email','mail_gmail_app_password'=>'nullable|string','mail_from_name'=>'nullable|max:100','mailtrap_host'=>'nullable|max:255','mailtrap_port'=>'nullable|integer','mailtrap_username'=>'nullable|max:255','mailtrap_password'=>'nullable']);foreach(['site_name','currency_symbol','pdf_footer','mail_gmail_address','mail_from_name','mailtrap_host','mailtrap_port','mailtrap_username'] as $key)AppSetting::updateOrCreate(['key'=>$key],['value'=>$data[$key]??null]);AppSetting::updateOrCreate(['key'=>'mail_sandbox_mode'],['value'=>$r->boolean('mail_sandbox_mode')?'1':'0']);foreach(['mail_gmail_app_password','mailtrap_password'] as $key)if(!empty($data[$key]))AppSetting::updateOrCreate(['key'=>$key],['value'=>$data[$key]]);if($r->hasFile('logo')){$old=AppSetting::value('logo');if($old)Storage::disk('public')->delete($old);AppSetting::updateOrCreate(['key'=>'logo'],['value'=>$r->file('logo')->store('branding','public')]);}return back()->with('success','Settings and mail configuration saved.');} public function testMail(Request $r){$data=$r->validate(['test_email'=>'required|email']);try{MailSettings::apply();Mail::to($data['test_email'])->send(new ContributorNotification('Festiva mail test','<p>Your Festiva mail configuration is working.</p>'));return response()->json(['ok'=>true]);}catch(\Throwable $e){return response()->json(['message'=>$e->getMessage()],422);}} }
